import { reindexBookmark } from "@/lib/db/repositories/search-index";
import type { Bookmark,Sort,View } from "@/lib/domain/types";
import { matches } from "@/lib/search/evaluate";
import { parseSearch } from "@/lib/search/parser";

const db=()=>{const value=database();migrate(value);return value;};
export function saveBookmark(raw:unknown,id?:string) { const input=bookmarkInput.parse(raw);const normalized=normalizeUrl(input.url);const existing=getByNormalizedUrl(db(),normalized);if(existing&&existing.id!==id)return{duplicate:existing};const bookmarkId=id||newId(),now=nowIso();db().transaction(()=>{if(id){db().prepare(`UPDATE bookmarks SET url_original=?,url_normalized=?,title=?,description=?,note=?,icon_url=?,is_favorite=?,is_read=?,updated_at=? WHERE id=?`).run(input.url,normalized,input.title,input.description,input.note,input.iconUrl,input.isFavorite?1:0,input.isRead?1:0,now,id);}else{db().prepare(`INSERT INTO bookmarks(id,url_original,url_normalized,title,description,note,icon_url,is_favorite,is_read,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).run(bookmarkId,input.url,normalized,input.title,input.description,input.note,input.iconUrl,input.isFavorite?1:0,input.isRead?1:0,now,now);}setTags(db(),bookmarkId,input.tags);reindexBookmark(db(),bookmarkId);})();return{bookmark:getBookmark(db(),bookmarkId)!}; }
export function listBookmarks(options:{view?:View;q?:string;sort?:Sort;tags?:string[]}) { const view=options.view||"all";let rows=db().prepare("SELECT * FROM bookmarks").all() as Record<string,string|number|null>[];let list=rows.map(r=>rowToBookmark(db(),r)).filter(b=>view==="archived"?!!b.archivedAt:!b.archivedAt).filter(b=>view!=="unread"||!b.isRead).filter(b=>view!=="favorites"||b.isFavorite);const ast=parseSearch(options.q||"");list=list.filter(b=>matches(b,ast));if(options.tags?.length)list=list.filter(b=>options.tags!.every(t=>b.tags.map(normalizeTag).includes(normalizeTag(t))));list.sort(options.sort==="title"?(a,b)=>a.title.localeCompare(b.title)||a.id.localeCompare(b.id):options.sort==="updated"?(a,b)=>b.updatedAt.localeCompare(a.updatedAt)||a.id.localeCompare(b.id):(a,b)=>b.createdAt.localeCompare(a.createdAt)||a.id.localeCompare(b.id));return list; }
