export function setArchived(id:string,value:boolean){db().prepare("UPDATE bookmarks SET archived_at=?,updated_at=? WHERE id=?").run(value?nowIso():null,nowIso(),id);}
export function deleteBookmark(id:string){db().transaction(()=>{db().prepare("DELETE FROM bookmark_search WHERE bookmark_id=?").run(id);db().prepare("DELETE FROM bookmarks WHERE id=?").run(id);})();}
export function bulk(ids:string[],action:string,tags:string[]=[]){const failures:string[]=[];let success=0;db().transaction(()=>{for(const id of ids){try{if(action==="archive")setArchived(id,true);else if(action==="read")setStatus(id,"is_read",true);else if(action==="unread")setStatus(id,"is_read",false);else if(action==="delete")deleteBookmark(id);else if(action==="tag"){const bookmark=getBookmark(db(),id);if(!bookmark)throw new Error();setTags(db(),id,[...bookmark.tags,...tags]);reindexBookmark(db(),id);}else throw new Error();success++;}catch{failures.push(id);}}})();return{success,failures};}
